  "Costales": "OTROS_0KG"
};

// Mínimo de compra por producto (unidades). Si un item del formato `items`
// no alcanza su mínimo, la tool RECHAZA el cálculo (ver checkMinimums más abajo).
// El formato legacy `cuentas` no tiene nombre de producto y por lo tanto NO
// puede validarse acá — ver advertencia_minimos en la salida.
const MIN_BY_PRODUCT = {
  "Sandalias Delgadas": 50,
  "Sandalias Gruesas": 50,
  "Pantuflas": 50,
  "Pantuflas Mono": 50,
  "Pantufla Moño Satin": 50,
  "Pantufla Moño Peluche": 50,
  "Cilindros": 40,
  "Vaso Popote 24 oz": 50,
  "Vasos Popote": 50,
  "Kits Anticrudas": 35,
  "Costales": 35,
  "Mandiles": 12
};

// Alias para tolerar variaciones del nombre que pueda mandar el agente
const PRODUCT_ALIASES = {
  "mandil": "Mandiles",
  "mandiles": "Mandiles",

  "kit anticruda": "Kits Anticrudas",
  "kits anticruda": "Kits Anticrudas",
  "kit anticrudas": "Kits Anticrudas",
  "kits anticrudas": "Kits Anticrudas",
  "costal": "Costales",
  "costales": "Costales",

  "cilindro": "Cilindros",
  "cilindros": "Cilindros",

  "sandalia delgada": "Sandalias Delgadas",
  "sandalias delgadas": "Sandalias Delgadas",
  "sandalia gruesa": "Sandalias Gruesas",
  "sandalias gruesas": "Sandalias Gruesas",

  "pantufla": "Pantuflas",
  "pantuflas": "Pantuflas",

  "pantufla mono": "Pantuflas Mono",
  "pantuflas mono": "Pantuflas Mono",
  "pantufla mono satin": "Pantufla Moño Satin",
  "pantuflas mono satin": "Pantufla Moño Satin",
  "pantufla mono satín": "Pantufla Moño Satin",
